add('lv', 2, 13, 'Agostinho', 'Temperaras com sal todo o cereal.', 'aplicacao');
add('lv', 4, 2, 'Wesley', 'Quando uma pessoa pecar.', 'aplicacao');
add('lv', 4, 20, 'Calvino', 'Fara com o bezerro do pecado.', 'teologico');
add('lv', 4, 35, 'João Crisóstomo', 'Todo o gordao sera queimado.', 'teologico');
