add('ec', 10, 10, 'Lloyd-Jones', 'Se o ferro está sem ponta. A ineficiência é resultado de não aperfeiçoar o instrumento.', 'aplicacao');
add('ec', 11, 1, 'Agostinho', 'Lança o teu pão sobre as águas. A generosidade é investimento eterno.', 'aplicacao');
add('ec', 12, 14, 'R.C. Sproul', 'Deus trará todo o julgamento. Nenhum ato passará despercebido.', 'teologico');
