add('ct', 3, 11, 'N.T. Wright', 'Saiam e vede. A procissão nupcial é modelo da celebração messiânica.', 'escatologico');
add('ct', 4, 10, 'Tim Keller', 'A bela entre as mulheres. A excelência da igreja é reflexo da graça de Cristo.', 'aplicacao');
add('ct', 6, 9, 'R.C. Sproul', 'Quem é esta que se levanta. A transformação pela graça é visível aos olhos.', 'aplicacao');
add('ct', 7, 10, 'Albert Barnes', 'Eu sou do meu amado. A posse mútua é essencial no relacionamento com Cristo.', 'aplicacao');
add('ct', 8, 6, 'Tomás de Aquino', 'A água e o sangue. O testemunho da paixão é confirmado pela autoridade divina.', 'teologico');
add('is', 2, 2, 'Calvino', 'No cumprimento dos tempos. A universalidade do reino messiânico transcende Israel.', 'escatologico');
add('is', 11, 6, 'Spurgeon', 'O menino guiará a criação. A era messiânica restaura a harmonia.', 'escatologico');
add('is', 25, 1, 'Albert Barnes', 'Tu és o meu Deus, eu te exaltarei. A gratidão é resposta natural à bondade divina.', 'aplicacao');
